ORKFLOW_READ_PRIVACY_UNAVAILABLE，不返回原文或改写后伪称原稿。该检测只覆盖已有公开secret规则，不能声称所有自由文本PII都自动审过；新内部展示仍依赖原安装role/markings/dataScope准入，无模型或外部发送。未知敏感字段failclosed，预算/佣金只是内部文本不能批准费用。\\n\\n复用原workflow._require_creator_brief和_draft不复制六purpose/四status/原ref状态机；按原最新createdAt/briefID排序，全部行先严格验证再每purpose保留首项，防被去重遮蔽坏旧行。响应沿用CreatorInternalWorkflowListResponse，仅当前授权保存草稿；真正全空返回items[]/count0，不合格任一源row明确unknown/error。此类无allowedCommands字段，不凭status approved、version或exactRef授予任何execute/人审/Provider/外发许可。\\n\\n测试RED missingmodule，再empty/nonempty sixpurpose/latestpurpose、同事务/role/readonly/isolation、outertenant/head/task drift/missingrevision+task/tasktype/hash/schema/spec/lifecycle/time/version/secret及unknowndetail拒绝、1000/1001/smallmanytotal/64KiBCASE NULL及finalsize，去重后坏旧行仍拒绝。累计旧workflow9、readCatalog/readHTTP、生产Brief现有邻域；真实owner隔离PG3表+FORCERLS/只SELECT角色/读写25006/并发snapshot，坏行与限额只在隔离fixture，原库不seed/造坏数据。之后codePrime exactsource/nativequality，rootTask另方案/Prime/RED只GET接线，最新已提交archive+freshAPI维护门+原真人GET/原菜单/原650/三视口Prime/准确Delivery/AuthorityPrime，再剩余helpers/fullC/自然链/安装/八场景/视觉/观察发布。\\n\\nFILE services/aos-api/aos_api/ecommerce_creator_internal_workflow.py SHA 0b5067fdffcf84448065798ef8c85e7349a757ab517a3b305d6de003554d13ad\\n\\\"\\\"\\\"Canonical internal-only creator drafting, review and history workflow.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom typing import Callable, Protocol\\n\\nfrom aos_api.aip_contracts import ResourceRef, TenantContext\\nfrom aos_api.aip_production_contract_store import AipProductionContractStore, ProductionContractError\\nfrom aos_api.aip_production_contracts import CreateBriefRequest, ReviseBriefRequest\\nfrom aos_api.aip_task_models import CreateTaskRequest\\nfrom aos_api.aip_task_store import AipTaskStore, AipTaskStoreError\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.ecommerce_creator_internal_workflow_contracts import (\\n    CreatorInternalWorkflowCommandRequest, CreatorInternalWorkflowCommandResponse,\\n    CreatorInternalWorkflowDraft, CreatorInternalWorkflowHistoryResponse,\\n    CreatorInternalWorkflowListResponse, CreatorInternalWorkflowReceipt,\\n    CreatorInternalWorkflowSideEffects,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nclass CreatorInternalWorkflowError(RuntimeError):\\n    code = \\\"CREATOR_INTERNAL_WORKFLOW_ERROR\\\"\\n\\n\\nclass CreatorInternalWorkflowConflict(CreatorInternalWorkflowError):\\n    code = \\\"CREATOR_INTERNAL_WORKFLOW_CONFLICT\\\"\\n\\n\\nclass TaskAuthority(Protocol):\\n    def create_task(self, scope, actor, idempotency_key, body): ...\\n\\n\\nclass BriefAuthority(Protocol):\\n    def create_brief(self, scope, actor, key, body): ...\\n    def revise_brief(self, scope, actor, brief_id, key, body): ...\\n    def get_brief(self, scope, brief_id, revision=None): ...\\n    def list_briefs(self, scope): ...\\n\\n\\nclass EcommerceCreatorInternalWorkflow:\\n    def __init__(self, task_store: TaskAuthority | None = None, brief_store: BriefAuthority | None = None, receipt_reader: Callable[[TenantScope, str, str], str | None] | None = None) -> None:\\n        self._tasks = task_store or AipTaskStore()\\n        self._briefs = brief_store or AipProductionContractStore()\\n        self._receipt_reader = receipt_reader or self._receipt\\n\\n    def execute(self, scope: TenantScope, actor: str, idempotency_key: str, body: CreatorInternalWorkflowCommandRequest) -> CreatorInternalWorkflowCommandResponse:\\n        key = idempotency_key.strip()\\n        if not key or len(key) > 120:\\n            raise CreatorInternalWorkflowConflict(\\\"Idempotency-Key must be 1..120 characters\\\")\\n        operation = \\\"task_brief.create\\\" if body.command == \\\"create\\\" else \\\"task_brief.revise\\\"\\n        receipt_key = f\\\"{key}:creator-brief\\\"\\n        replay = self._receipt_reader(scope, operation, receipt_key) is not None\\n        try:\\n            if body.command == \\\"create\\\":\\n                task = self._tasks.create_task(scope, actor, f\\\"{key}:creator-task\\\", CreateTaskRequest(\\n                    type=\\\"ecommerce.workshop.creator_internal_task\\\", title=body.title,\\n                    description=\\\"达人邀约驾驶舱内部业务准备与审核任务。\\\",\\n                    goal={\\\"purpose\\\": body.purpose, \\\"externalEffectsAllowed\\\": False},\\n                ))\\n                draft = self._briefs.create_brief(scope, actor, receipt_key, CreateBriefRequest(\\n                    task_id=task.id, brief_type=\\\"creator_internal_workflow\\\", schema_ref=self._schema_ref(), spec=self._spec(body, \\\"draft\\\"),\\n                ))\\n                task_id = task.id\\n            else:\\n                assert body.draft_ref is not None and body.expected_version is not None\\n                current = self._briefs.get_brief(scope, body.draft_ref.resource_id)\\n                self._require_creator_brief(current)\\n                self._require_exact(current, body.draft_ref, body.expected_version)\\n                self._require_transition(current.spec.get(\\\"status\\\", \\\"draft\\\"), body.command)\\n                if current.spec[\\\"purpose\\\"] != body.purpose:\\n                    raise CreatorInternalWorkflowConflict(\\\"creator workflow purpose is immutable\\\")\\n                if body.command == \\\"restore\\\":\\n                    assert body.restore_revision is not None\\n                    if body.restore_revision >= current.revision:\\n                        raise CreatorInternalWorkflowConflict(\\n                            \\\"restoreRevision must reference an earlier revision\\\"\\n                        )\\n                    previous = self._briefs.get_brief(scope, current.brief_id, body.restore_revision)\\n                    self._require_creator_brief(previous)\\n                    if previous.spec[\\\"purpose\\\"] != current.spec[\\\"purpose\\\"]:\\n                        raise CreatorInternalWorkflowConflict(\\\"creator workflow history purpose drift\\\")\\n                    spec = dict(previous.spec)\\n                    spec[\\\"status\\\"] = \\\"draft\\\"\\n                    spec[\\\"restoredFromRevision\\\"] = body.restore_revision\\n                else:\\n                    status = {\\\"save\\\": \\\"draft\\\", \\\"submit_review\\\": \\\"in_review\\\", \\\"approve\\\": \\\"approved\\\", \\\"reject\\\": \\\"rejected\\\"}[body.command]\\n                    spec = self._spec(body, status)\\n                draft = self._briefs.revise_brief(scope, actor, current.brief_id, receipt_key, ReviseBriefRequest(\\n                    expected_version=body.expected_version, brief_type=\\\"creator_internal_workflow\\\", schema_ref=self._schema_ref(), spec=spec,\\n                ))\\n                task_id = draft.task_id\\n        except (ProductionContractError, AipTaskStoreError, ValueError) as exc:\\n            raise CreatorInternalWorkflowConflict(str(exc)) from exc\\n        receipt_id = self._receipt_reader(scope, operation, receipt_key)\\n        if receipt_id is None:\\n            raise CreatorInternalWorkflowError(\\\"canonical Brief Receipt is unavailable\\\")\\n        return CreatorInternalWorkflowCommandResponse(\\n            tenant=TenantContext(org_id=scope.org_id, project_id=scope.project_id), command=body.command,\\n            task_id=task_id, draft=self._draft(draft),\\n            receipt=CreatorInternalWorkflowReceipt(receipt_id=receipt_id, operation=operation, idempotency_key=receipt_key, replay=replay),\\n            side_effects=CreatorInternalWorkflowSideEffects(),\\n            message={\\\"create\\\":\\\"内部业务草稿已创建。\\\",\\\"save\\\":\\\"修改已保存为新版本。\\\",\\\"submit_review\\\":\\\"已提交内部审核。\\\",\\\"approve\\\":\\\"内部审核已批准。\\\",\\\"reject\\\":\\\"内部审核已驳回。\\\",\\\"restore\\\":\\\"历史版本已恢复为新草稿。\\\"}[body.command],\\n        )\\n\\n    def history(self, scope: TenantScope, brief_id: str) -> CreatorInternalWorkflowHistoryResponse:\\n        try:\\n            current = self._briefs.get_brief(scope, brief_id)\\n            self._require_creator_brief(current)\\n            items = []\\n            for revision in range(1, current.revision + 1):\\n                value = self._briefs.get_brief(scope, brief_id, revision)\\n                self._require_creator_brief(value)\\n                items.append(self._draft(value, version=revision))\\n        except (ProductionContractError, ValueError) as exc:\\n            raise CreatorInternalWorkflowConflict(str(exc)) from exc\\n        return CreatorInternalWorkflowHistoryResponse(tenant=TenantContext(org_id=scope.org_id, project_id=scope.project_id), items=items, count=len(items))\\n\\n    def list(self, scope: TenantScope) -> CreatorInternalWorkflowListResponse:\\n        try:\\n            values = self._briefs.list_briefs(scope).items\\n            items = []\\n            seen_purposes: set[str] = set()\\n            for value in values:\\n                if value.brief_type != \\\"creator_internal_workflow\\\":\\n                    continue\\n                self._require_creator_brief(value)\\n                purpose = value.spec[\\\"purpose\\\"]\\n                if purpose in seen_purposes:\\n                    continue\\n                seen_purposes.add(purpose)\\n                items.append(self._draft(value))\\n        except (ProductionContractError, ValueError) as exc:\\n            raise CreatorInternalWorkflowConflict(str(exc)) from exc\\n        return CreatorInternalWorkflowListResponse(\\n            tenant=TenantContext(org_id=scope.org_id, project_id=scope.project_id),\\n            items=items,\\n            count=len(items),\\n        )\\n\\n    @staticmethod\\n    def _schema_ref() -> ResourceRef:\\n        return ResourceRef(resource_type=\\\"CreatorInternalWorkflowSchema\\\", resource_id=\\\"schema://aos/ecommerce/creator-internal-workflow/v1\\\", revision=\\\"1\\\", authority=\\\"aos://ecommerce-workshop/creator-growth\\\")\\n\\n    @staticmethod\\n    def _spec(body: CreatorInternalWorkflowCommandRequest, status: str) -> dict:\\n        return {\\\"purpose\\\": body.purpose, \\\"title\\\": body.title, \\\"summary\\\": body.summary, \\\"details\\\": body.details, \\\"status\\\": status, \\\"externalEffectsAllowed\\\": False}\\n\\n    @staticmethod\\n    def _draft(value, *, version: int | None = None) -> CreatorInternalWorkflowDraft:\\n        return CreatorInternalWorkflowDraft(resource_id=value.brief_id, revision=value.revision, version=version or value.version, content_hash=value.content_hash, purpose=value.spec[\\\"purpose\\\"], title=value.spec[\\\"title\\\"], summary=value.spec[\\\"summary\\\"], details=value.spec.get(\\\"details\\\", {}), status=value.spec.get(\\\"status\\\", \\\"draft\\\"))\\n\\n    @classmethod\\n    def _require_creator_brief(cls, value) -> None:\\n        if value.brief_type != \\\"creator_internal_workflow\\\" or value.schema_ref != cls._schema_ref():\\n            raise CreatorInternalWorkflowConflict(\\\"task brief is not a creator internal workflow\\\")\\n        spec = value.spec\\n        if not isinstance(spec, dict) or spec.get(\\\"externalEffectsAllowed\\\") is not False:\\n            raise CreatorInternalWorkflowConflict(\\\"creator workflow safety marker is invalid\\\")\\n        if spec.get(\\\"purpose\\\") not in {\\\"candidate_import\\\", \\\"outreach_batch\\\", \\\"outreach_message\\\", \\\"collaboration\\\", \\\"delivery_check\\\", \\\"relationship_plan\\\"}:\\n            raise CreatorInternalWorkflowConflict(\\\"creator workflow purpose is invalid\\\")\\n        if spec.get(\\\"status\\\") not in {\\\"draft\\\", \\\"in_review\\\", \\\"approved\\\", \\\"rejected\\\"}:\\n            raise CreatorInternalWorkflowConflict(\\\"creator workflow status is invalid\\\")\\n        if not isinstance(spec.get(\\\"title\\\"), str) or not isinstance(spec.get(\\\"summary\\\"), str) or not isinstance(spec.get(\\\"details\\\", {}), dict):\\n            raise CreatorInternalWorkflowConflict(\\\"creator workflow content is invalid\\\")\\n\\n    @staticmethod\\n    def _require_exact(current, exact, expected_version: int) -> None:\\n        if current.brief_id != exact.resource_id or current.revision != exact.revision or current.content_hash != exact.content_hash or current.version != expected_version:\\n            raise CreatorInternalWorkflowConflict(\\\"draft exact ref or expectedVersion is stale\\\")\\n\\n    @staticmethod\\n    def _require_transition(current_status: str, command: str) -> None:\\n        allowed = {\\n            \\\"save\\\": {\\\"draft\\\", \\\"rejected\\\"},\\n            \\\"submit_review\\\": {\\\"draft\\\", \\\"rejected\\\"},\\n            \\\"approve\\\": {\\\"in_review\\\"},\\n            \\\"reject\\\": {\\\"in_review\\\"},\\n            \\\"restore\\\": {\\\"draft\\\", \\\"in_review\\\", \\\"approved\\\", \\\"rejected\\\"},\\n        }\\n        if current_status not in allowed[command]:\\n            raise CreatorInternalWorkflowConflict(\\n                f\\\"command {command} is not allowed from status {current_status}\\\"\\n            )\\n\\n    @staticmethod\\n    def _receipt(scope: TenantScope, operation: str, key: str) -> str | None:\\n        with connect_read_only(scope) as conn:\\n            row = conn.execute(\\\"SELECT receipt_id FROM aip_production_contract_receipt WHERE org_id=%s AND project_id=%s AND operation=%s AND idempotency_key=%s\\\", (*scope.key, operation, key)).fetchone()\\n        return str(row[\\\"receipt_id\\\"]) if row else None\\n\\nFILE services/aos-api/aos_api/ecommerce_creator_internal_workflow_contracts.py SHA 560a8da03e75ab1bdad351ce5918d60cd3f48a1dfa8e5140cf06432f8571e33c\\n\\\"\\\"\\\"Contracts for the tenant-safe creator internal workflow.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom typing import Any, Literal\\n\\nfrom pydantic import Field, model_validator\\n\\nfrom aos_api.aip_contracts import AipContractModel, TenantContext\\nfrom aos_api.aip_production_contracts import ExactRevisionRef\\n\\nCreatorWorkflowCommand = Literal[\\\"create\\\", \\\"save\\\", \\\"submit_review\\\", \\\"approve\\\", \\\"reject\\\", \\\"restore\\\"]\\nCreatorWorkflowPurpose = Literal[\\\"candidate_import\\\", \\\"outreach_batch\\\", \\\"outreach_message\\\", \\\"collaboration\\\", \\\"delivery_check\\\", \\\"relationship_plan\\\"]\\nCreatorWorkflowStatus = Literal[\\\"draft\\\", \\\"in_review\\\", \\\"approved\\\", \\\"rejected\\\"]\\n\\n\\nclass CreatorInternalWorkflowCommandRequest(AipContractModel):\\n    command: CreatorWorkflowCommand\\n    purpose: CreatorWorkflowPurpose\\n    title: str = Field(min_length=2, max_length=160)\\n    summary: str = Field(min_length=2, max_length=2000)\\n    details: dict[str, Any] = Field(default_factory=dict)\\n    draft_ref: ExactRevisionRef | None = None\\n    expected_version: int | None = Field(default=None, ge=1)\\n    restore_revision: int | None = Field(default=None, ge=1)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _revision_contract(self) -> \\\"CreatorInternalWorkflowCommandRequest\\\":\\n        revising = self.command != \\\"create\\\"\\n        if revising != (self.draft_ref is not None and self.expected_version is not None):\\n            raise ValueError(\\\"revision commands require draftRef and expectedVersion\\\")\\n        if self.draft_ref and self.draft_ref.resource_type != \\\"TaskBriefRevision\\\":\\n            raise ValueError(\\\"draftRef must reference TaskBriefRevision\\\")\\n        if (self.command == \\\"restore\\\") != (self.restore_revision is not None):\\n            raise ValueError(\\\"restore requires restoreRevision and other commands forbid it\\\")\\n        return self\\n\\n\\nclass CreatorInternalWorkflowDraft(ExactRevisionRef):\\n    resource_type: Literal[\\\"TaskBriefRevision\\\"] = \\\"TaskBriefRevision\\\"\\n    version: int = Field(ge=1)\\n    purpose: CreatorWorkflowPurpose\\n    title: str\\n    summary: str\\n    details: dict[str, Any]\\n    status: CreatorWorkflowStatus\\n\\n\\nclass CreatorInternalWorkflowReceipt(AipContractModel):\\n    receipt_id: str\\n    operation: Literal[\\\"task_brief.create\\\", \\\"task_brief.revise\\\"]\\n    idempotency_key: str\\n    replay: bool\\n\\n\\nclass CreatorInternalWorkflowSideEffects(AipContractModel):\\n    provider_invocation_count: Literal[0] = 0\\n    external_outreach_count: Literal[0] = 0\\n    contract_signature_count: Literal[0] = 0\\n    business_mutation_count: Literal[0] = 0\\n\\n\\nclass CreatorInternalWorkflowCommandResponse(AipContractModel):\\n    tenant: TenantContext\\n    command: CreatorWorkflowCommand\\n    task_id: str\\n    draft: CreatorInternalWorkflowDraft\\n    receipt: CreatorInternalWorkflowReceipt\\n    side_effects: CreatorInternalWorkflowSideEffects\\n    message: str\\n\\n\\nclass CreatorInternalWorkflowHistoryResponse(AipContractModel):\\n    tenant: TenantContext\\n    items: list[CreatorInternalWorkflowDraft]\\n    count: int = Field(ge=0)\\n\\n\\nclass CreatorInternalWorkflowListResponse(AipContractModel):\\n    tenant: TenantContext\\n    items: list[CreatorInternalWorkflowDraft]\\n    count: int = Field(ge=0)\\n\\nFILE services/aos-api/alembic/versions/w2_001_brief_evidence.py SHA 49bd74820e667cd0c9f1033525a00810d590ea07d5a04a12c6d0cb327125abfd\\n\\\"\\\"\\\"Add W2-A task brief and evidence bundle authority.\\n\\nRevision ID: w2_001\\nRevises: aip6_004\\nCreate Date: 2026-08-13\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom collections.abc import Sequence\\nfrom alembic import op\\n\\nrevision: str = \\\"w2_001\\\"\\ndown_revision: str | Sequence[str] | None = \\\"aip6_004\\\"\\nbranch_labels = None\\ndepends_on = None\\n\\nTABLES = (\\\"aip_task_brief_revision\\\", \\\"aip_task_brief_head\\\", \\\"aip_evidence_bundle_revision\\\", \\\"aip_production_contract_receipt\\\")\\n\\n\\ndef _tenant_table(name: str) -> None:\\n    op.execute(f\\\"ALTER TABLE {name} ENABLE ROW LEVEL SECURITY\\\")\\n    op.execute(f\\\"ALTER TABLE {name} FORCE ROW LEVEL SECURITY\\\")\\n    op.execute(f\\\"\\\"\\\"CREATE POLICY tenant_scope_{name}_w2 ON {name} TO aos_runtime\\n        USING (org_id=NULLIF(current_setting('aos.org_id',true),'') AND project_id=NULLIF(current_setting('aos.project_id',true),''))\\n        WITH CHECK (org_id=NULLIF(current_setting('aos.org_id',true),'') AND project_id=NULLIF(current_setting('aos.project_id',true),''))\\\"\\\"\\\")\\n    op.execute(f\\\"GRANT SELECT,INSERT,UPDATE ON {name} TO aos_runtime\\\")\\n\\n\\ndef upgrade() -> None:\\n    op.execute(\\\"\\\"\\\"CREATE TABLE aip_task_brief_head (\\n      org_id TEXT NOT NULL, project_id TEXT NOT NULL, brief_id TEXT NOT NULL,\\n      task_id TEXT NOT NULL, current_revision BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 1,\\n      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n      PRIMARY KEY(org_id,project_id,brief_id), CHECK(current_revision>=1), CHECK(version>=1),\\n      FOREIGN KEY(org_id,project_id,task_id) REFERENCES aip_task(org_id,project_id,task_id))\\\"\\\"\\\")\\n    op.execute(\\\"\\\"\\\"CREATE TABLE aip_task_brief_revision (\\n      org_id TEXT NOT NULL, project_id TEXT NOT NULL, brief_id TEXT NOT NULL, revision BIGINT NOT NULL,\\n      task_id TEXT NOT NULL, brief_type TEXT NOT NULL, schema_ref JSONB NOT NULL, spec JSONB NOT NULL,\\n      content_hash TEXT NOT NULL, lifecycle TEXT NOT NULL, created_by TEXT NOT NULL,\\n      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n      PRIMARY KEY(org_id,project_id,brief_id,revision),\\n      CHECK(revision>=1), CHECK(content_hash ~ '^[0-9a-f]{64}$'),\\n      CHECK(lifecycle IN ('draft','frozen','withdrawn','superseded')),\\n      CHECK(jsonb_typeof(schema_ref)='object'), CHECK(jsonb_typeof(spec)='object'),\\n      FOREIGN KEY(org_id,project_id,task_id) REFERENCES aip_task(org_id,project_id,task_id),\\n      FOREIGN KEY(org_id,project_id,brief_id) REFERENCES aip_task_brief_head(org_id,project_id,brief_id)\\n        DEFERRABLE INITIALLY DEFERRED)\\\"\\\"\\\")\\n    op.execute(\\\"\\\"\\\"CREATE TABLE aip_evidence_bundle_revision (\\n      org_id TEXT NOT NULL, project_id TEXT NOT NULL, bundle_id TEXT NOT NULL, revision BIGINT NOT NULL,\\n      brief_ref JSONB NOT NULL, subject_refs JSONB NOT NULL, cutoff_at TIMESTAMPTZ NOT NULL,\\n      item_refs JSONB NOT NULL, coverage TEXT NOT NULL, missing JSONB NOT NULL, conflicts JSONB NOT NULL,\\n      uncertainties JSONB NOT NULL, freshness TEXT NOT NULL, marking JSONB NOT NULL, license_summary JSONB NOT NULL,\\n      content_hash TEXT NOT NULL, lifecycle TEXT NOT NULL, created_by TEXT NOT NULL,\\n      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n      PRIMARY KEY(org_id,project_id,bundle_id,revision), UNIQUE(org_id,project_id,bundle_id,content_hash),\\n      CHECK(revision>=1), CHECK(content_hash ~ '^[0-9a-f]{64}$'),\\n      CHECK(coverage IN ('complete','partial','blocked','unknown')),\\n      CHECK(freshness IN ('fresh','stale','blocked','unknown')),\\n      CHECK(lifecycle IN ('frozen','withdrawn','superseded')),\\n      CHECK(jsonb_typeof(brief_ref)='object'), CHECK(jsonb_typeof(subject_refs)='array'),\\n      CHECK(jsonb_typeof(item_refs)='array'), CHECK(jsonb_typeof(missing)='array'),\\n      CHECK(jsonb_typeof(conflicts)='array'), CHECK(jsonb_typeof(uncertainties)='array'))\\\"\\\"\\\")\\n    op.execute(\\\"\\\"\\\"CREATE TABLE aip_production_contract_receipt (\\n      org_id TEXT NOT NULL, project_id TEXT NOT NULL, receipt_id TEXT NOT NULL,\\n      operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL,\\n      result_ref JSONB NOT NULL, created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n      PRIMARY KEY(org_id,project_id,receipt_id), UNIQUE(org_id,project_id,operation,idempotency_key),\\n      CHECK(request_hash ~ '^[0-9a-f]{64}$'), CHECK(jsonb_typeof(result_ref)='object'))\\\"\\\"\\\")\\n    for table in TABLES:\\n        _tenant_table(table)\\n    op.execute(\\\"REVOKE UPDATE ON aip_task_brief_revision, aip_evidence_bundle_revision, aip_production_contract_receipt FROM aos_runtime\\\")\\n    op.execute(\\\"CREATE INDEX aip_brief_task_idx ON aip_task_brief_head(org_id,project_id,task_id,updated_at DESC)\\\")\\n    op.execute(\\\"CREATE INDEX aip_bundle_cutoff_idx ON aip_evidence_bundle_revision(org_id,project_id,cutoff_at DESC,bundle_id)\\\")\\n\\n\\ndef downgrade() -> None:\\n    for table in reversed(TABLES):\\n        op.execute(f\\\"DROP TABLE IF EXISTS {table} CASCADE\\\")\\n\\nFILE .evidence/qyh-creator-workflow-read-admission-20261014/audit-findings-r1.md SHA 7bf0f0b3d2773b68d3f4464525453e3d3fb8190ecd93a59463e953c1ac807b12\\n# 达人内部工作流GET第一阶段只读审计\\n\\nRules/231完整Goal/唯一m1写者，同owner Task/base2030/16:00UTC已受支持登记，无产品修改。原数据161/650/绑定0只读，HostworkerProviderOFF/旧unknown12Run/禁用Schedule/Source/noPush全部持续。上一lifecycle读取波精确Delivery完成，仅帮助读取，不是业务链或全Goal完成。\\n\\n实际路径：router list_creator_internal_workflows `/views/creator-growth/workflow/drafts` 当前CatalogDependency→原creator安装门→workflow.list(scope)。default EcommerceCreatorInternalWorkflow实际实例化AipTaskStore及AipProductionContractStore。list未调用create_task/execute/receipt或TaskStore读取；直接 `_briefs.list_briefs(scope).items`，随后Python按brief_type过滤、精确CreatorSchemaRef及externalfalse/六purpose/四status/title/summary/details校验，按purpose仅保留已排序第一项。DTO包含exactRef/version/purpose/title/summary/details/status；没有allowedCommands字段，不能解释approved为当前真人许可或自动运行。\\n\\n实际Store list_briefs单个conn SELECT当前head+revision同org/project/briefId/revisionJOIN，WHEREheadtenant，ORDERcreated_atDESC/briefId。但先SELECT revision.*读所有业务类型、无LIMIT和spec字节上限，然后才Python过滤creator。这是确定性准入缺口：不能仅将本GET改ReadCatalog白名单。`_brief`用参数scope生成DTO tenant，未额外检查rowoutertenant/head字段一致；SQLtenant正面防线存在但还需严格decode验证。返回spec.details任意JSON，需明确只给授权内部业务所需字段、禁止凭其命令/凭据/ref产生调用。\\n\\n需后续审计：固定CreatorSchemaRef/type在SQL筛选与Python严格复核、outertenant/headrevision+version/taskID一致、canonical_hash原briefType/schemaRef/spec完整重算（create_brief已有原canonical规则，复用不另invent）；是否任务type需要匹配creator_internal_task必须据产品/技术方案裁决；spec字段/嵌套details大小与隐私授权、索引/limit+1/rows及total超限503不截断假零；同事务一致性、真实空/unknown故障/非法content、typed响应对version/status/canonicalhead语义不能伪造；合法无readonlymarker旧list/history和所有execute写门保持。\\n\\n下一安全步骤：补齐DDL/RLS/原hash与前端details输入输出/产品技术方案及权限数据范围，形成专用有界内部工作流读取方案并独立Prime。需要新模块/test或Store修复另登记精确文件Task/Lease，当前Scope只router/http/evidence/D-wave，不得擅自修改共享AIP生产Store。未完成审计与门之前不开放该GET，不把原当前404换成假空200。完整C最终真人人预算/原部署/自然CaseRun→建议评审内容能力人审续跑总控Wiki/安装生命周期/八场景/全视觉/连续发布Goal继续。\\n\\n进一步确定的关键缺口：AipProductionContractStore默认 `_connect_factory=connect_factory or db_connect`，其中db_connect明确为 `aos_api.db.connect`（read_only=False），不是connect_read_only；原wrapper的整体只读边界不能替代该reader本身的事务约束。新读取方案必须明确使用现有connect_read_only(scope)/REPEATABLE_READ及role/tenant验证，不可拿SQL只有SELECT当成连接只读保证。此项与无LIMIT/读取所有brief类型共同阻止机械放开ReadCatalog。\\n\\nORIGINAL FUNCTION canonical_hash\\ndef canonical_hash(value: Any) -> str:\\n    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), default=str)\\n    return hashlib.sha256(raw.encode()).hexdigest()\\nORIGINAL FUNCTION create_brief\\ndef create_brief(self, scope: TenantScope, actor: str, key: str, body: CreateBriefRequest) -> TaskBriefRevision:\\n        payload = body.model_dump(mode=\\\"json\\\", by_alias=True)\\n        request_hash = canonical_hash(payload)\\n        with self._contract_connect_factory(scope) as conn:\\n            replay = self._replay(conn, scope, \\\"task_brief.create\\\", key, request_hash)\\n            if replay:\\n                return self.get_brief(scope, replay[\\\"resourceId\\\"], int(replay[\\\"revision\\\"]), conn=conn)\\n            if not conn.execute(\\\"SELECT 1 FROM aip_task WHERE org_id=%s AND project_id=%s AND task_id=%s\\\", (*scope.key, body.task_id)).fetchone():\\n                raise ProductionContractDependencyBlocked(\\\"task not found in tenant scope\\\")\\n            brief_id = f\\\"brief-{uuid.uuid4().hex[:20]}\\\"\\n            content_hash = canonical_hash({\\\"briefType\\\": body.brief_type, \\\"schemaRef\\\": payload[\\\"schemaRef\\\"], \\\"spec\\\": body.spec})\\n            conn.execute(\\\"INSERT INTO aip_task_brief_head(org_id,project_id,brief_id,task_id,current_revision,version) VALUES(%s,%s,%s,%s,1,1)\\\", (*scope.key, brief_id, body.task_id))\\n            row = conn.execute(\\\"\\\"\\\"INSERT INTO aip_task_brief_revision(org_id,project_id,brief_id,revision,task_id,brief_type,schema_ref,spec,content_hash,lifecycle,created_by)\\n                VALUES(%s,%s,%s,1,%s,%s,%s::jsonb,%s::jsonb,%s,'draft',%s) RETURNING *\\\"\\\"\\\",\\n                (*scope.key, brief_id, body.task_id, body.brief_type, self._json(payload[\\\"schemaRef\\\"]), self._json(body.spec), content_hash, actor)).fetchone()\\n            self._receipt(conn, scope, \\\"task_brief.create\\\", key, request_hash, {\\\"resourceType\\\":\\\"TaskBriefRevision\\\",\\\"resourceId\\\":brief_id,\\\"revision\\\":1,\\\"contentHash\\\":content_hash}, actor)\\n            conn.commit()\\n            return self._brief(scope, row, 1)\\nORIGINAL FUNCTION revise_brief\\ndef revise_brief(self, scope: TenantScope, actor: str, brief_id: str, key: str, body: ReviseBriefRequest) -> TaskBriefRevision:\\n        payload = body.model_dump(mode=\\\"json\\\", by_alias=True); request_hash = canonical_hash({\\\"briefId\\\":brief_id, **payload})\\n        with self._contract_connect_factory(scope) as conn:\\n            replay = self._replay(conn, scope, \\\"task_brief.revise\\\", key, request_hash)\\n            if replay: return self.get_brief(scope, brief_id, int(replay[\\\"revision\\\"]), conn=conn)\\n            head = conn.execute(\\\"SELECT * FROM aip_task_brief_head WHERE org_id=%s AND project_id=%s AND brief_id=%s FOR UPDATE\\\", (*scope.key, brief_id)).fetchone()\\n            if not head: raise ProductionContractNotFound(\\\"task brief not found\\\")\\n            if int(head[\\\"version\\\"]) != body.expected_version: raise ProductionContractConflict(\\\"stale task brief version\\\")\\n            current = self.get_brief(scope, brief_id, int(head[\\\"current_revision\\\"]), conn=conn)\\n            if current.lifecycle != BriefLifecycle.DRAFT: raise ProductionContractConflict(\\\"only a draft brief can be revised\\\")\\n            revision = int(head[\\\"current_revision\\\"]) + 1\\n            content_hash = canonical_hash({\\\"briefType\\\":body.brief_type,\\\"schemaRef\\\":payload[\\\"schemaRef\\\"],\\\"spec\\\":body.spec})\\n            row = conn.execute(\\\"\\\"\\\"INSERT INTO aip_task_brief_revision(org_id,project_id,brief_id,revision,task_id,brief_type,schema_ref,spec,content_hash,lifecycle,created_by)\\n                VALUES(%s,%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s,'draft',%s) RETURNING *\\\"\\\"\\\",\\n                (*scope.key, brief_id, revision, head[\\\"task_id\\\"], body.brief_type, self._json(payload[\\\"schemaRef\\\"]), self._json(body.spec), content_hash, actor)).fetchone()\\n            conn.execute(\\\"UPDATE aip_task_brief_head SET current_revision=%s,version=version+1,updated_at=NOW() WHERE org_id=%s AND project_id=%s AND brief_id=%s\\\", (revision,*scope.key,brief_id))\\n            self._receipt(conn,scope,\\\"task_brief.revise\\\",key,request_hash,{\\\"resourceType\\\":\\\"TaskBriefRevision\\\",\\\"resourceId\\\":brief_id,\\\"revision\\\":revision,\\\"contentHash\\\":content_hash},actor)\\n            conn.commit(); return self._brief(scope,row,int(head[\\\"version\\\"])+1)\\nORIGINAL FUNCTION list_briefs\\ndef list_briefs(self, scope: TenantScope) -> TaskBriefListResponse:\\n        with self._connect_factory(scope) as conn:\\n            rows = conn.execute(\\n                \\\"\\\"\\\"SELECT revision.*, head.version\\n                FROM aip_task_brief_head head\\n                JOIN aip_task_brief_revision revision\\n                  ON revision.org_id=head.org_id AND revision.project_id=head.project_id\\n                 AND revision.brief_id=head.brief_id AND revision.revision=head.current_revision\\n                WHERE head.org_id=%s AND head.project_id=%s\\n                ORDER BY revision.created_at DESC, revision.brief_id\\\"\\\"\\\",\\n                scope.key,\\n            ).fetchall()\\n            items = [self._brief(scope, row, int(row[\\\"version\\\"])) for row in rows]\\n            return TaskBriefListResponse(\\n                tenant=TenantContext(org_id=scope.org_id, project_id=scope.project_id),\\n                items=items,\\n                count=len(items),\\n            )\\nORIGINAL FUNCTION _brief\\ndef _brief(self,scope:TenantScope,row:Any,version:int)->TaskBriefRevision:\\n        return TaskBriefRevision(tenant=TenantContext(org_id=scope.org_id,project_id=scope.project_id),brief_id=row[\\\"brief_id\\\"],task_id=row[\\\"task_id\\\"],revision=int(row[\\\"revision\\\"]),version=version,brief_type=row[\\\"brief_type\\\"],schema_ref=ResourceRef.model_validate(self._load(row[\\\"schema_ref\\\"])),spec=self._load(row[\\\"spec\\\"]),content_hash=row[\\\"content_hash\\\"],lifecycle=BriefLifecycle(row[\\\"lifecycle\\\"]),created_by=row[\\\"created_by\\\"],created_at=row[\\\"created_at\\\"])\\nEXISTING redaction contract _SENSITIVE_KEYS = re.compile(\\n    r\\\"authorization|token|secret|password|passwd|cookie|api[_-]?key|email|phone|mobile|address|id[_-]?card|ssn\\\",\\n    re.IGNORECASE,\\n)\\n_BEARER = re.compile(r\\\"(?i)bearer\\\\s+[A-Za-z0-9._~+\\\\-/=]+\\\")\\n_EMAIL = re.compile(r\\\"\\\\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\\\\.[A-Z]{2,}\\\\b\\\", re.IGNORECASE)\\n_PHONE = re.compile(r\\\"(?<!\\\\d)1[3-9]\\\\d{9}(?!\\\\d)\\\")\\n_SECRET = re.compile(r\\\"\\\\b(?:sk|pk)-[A-Za-z0-9_-]{8,}\\\\b\\\")\\n\\n\\ndef redact_sensitive(value: Any) -> Any:\\n    if isinstance(value, Mapping):\\n        return {\\n            str(key): \\\"[REDACTED]\\\" if _SENSITIVE_KEYS.search(str(key)) else redact_sensitive(child)\\n            for key, child in value.items()\\n        }\\n    if isinstance(value, (list, tuple, set)):\\n        return [redact_sensitive(child) for child in value]\\n    if isinstance(value, str):\\n        result = _BEARER.sub(\\\"Bearer [REDACTED]\\\", value)\\n        result = _EMAIL.sub(\\\"[REDACTED]\\\", result)\\n        result = _PHONE.sub(\\\"[REDACTED]\\\", result)\\n        return _SECRET.sub(\\\"[REDACTED]\\\", result)\\n    return value\\n\\nEXISTING real frontend values\\n  const values = { title: title.trim(), summary: summary.trim(), details: { owner: owner.trim(), productRef, productName: selectedProduct?.title ?? detailText(current?.details, \\\"productName\\\"), candidateSource: candidateSource.trim(), contentCategory: contentCategory.trim(), audienceScale: audienceScale.trim(), channel: channel.trim(), budget: budget.trim(), commission: commission.trim(), benefits: benefits.trim(), deliverables: deliverables.trim(), evidence: evidence.trim(), schedule: schedule.trim() } };\"}}"}],"timestamp":1791982657330}}
